# also include 0 comps (comps() skipped 0 since falsy)
def comps0(g):
    from collections import deque
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen and g[i][j] in (0,) or (g[i][j] and (i,j) not in seen):
                pass
    return out
# simpler: general comps over all cells, grouping same value
def comps_all(g):
    from collections import deque
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                ys=[a for a,b in cells]; xs=[b for a,b in cells]
                t,l=min(ys),min(xs)
                pat=tuple(tuple(1 if (t+a,l+b) in set(cells) else 0 for b in range(max(xs)-l+1)) for a in range(max(ys)-t+1))
                out.append((c,cells,pat))
    return out
