# duplicate pattern groups in each grid
def dups(CA):
    from collections import defaultdict
    g=defaultdict(list)
    for c,cells,pat in CA: g[pat].append((c,cells))
    return {p:v for p,v in g.items() if len(v)>1 and len(p)>=1}
